import { sellerMarkupRange, formatSellerMarkupRange, sellerMarkupTone } from "./sellerMarkup";
import { resolveItemImageForItem } from "./itemPresentation";
import { fmt } from "./parseItem";

// Builds the per-listing rows for the seller export card from the same
// match data the seller panel renders, so the numbers can never drift.
// Sorted latest-first (most recently seen wins); the card shows the first
// STRIP_LIMIT rows plus an overflow count.
export const SELLER_EXPORT_STRIP_LIMIT = 5;

export function buildSellerListings(matches, rowsByKey, limit = SELLER_EXPORT_STRIP_LIMIT) {
  const getRow = rowsByKey?.get
    ? (key) => rowsByKey.get(key)
    : (key) => rowsByKey?.[key];
  const rows = (matches || []).map((match) => {
    const row = getRow?.(match.itemKey);
    const range = sellerMarkupRange(match, row);
    const median = Number(row?.median || 0);
    const minPrice = Number(match.minUnitPrice || 0);
    const maxPrice = Number(match.maxUnitPrice || 0);
    const priceLabel =
      minPrice > 0
        ? minPrice === maxPrice
          ? fmt(minPrice)
          : `${fmt(minPrice)}–${fmt(maxPrice)}`
        : "—";
    const seenMs = Number(match.latestSeenMs || 0);
    return {
      key: match.itemKey,
      name: row?.name || match.itemKey,
      priceLabel,
      markupText: formatSellerMarkupRange(range),
      tone: sellerMarkupTone(range),
      medianLabel: median > 0 ? fmt(median) : "—",
      offers: Number(match.listingCount || 0),
      iconSrc: resolveItemImageForItem({ key: match.itemKey })?.src || null,
      iconPixelated: resolveItemImageForItem({ key: match.itemKey })?.pixelated !== false,
      // No timestamp sorts last; among them keep original order.
      sortKey: seenMs > 0 ? -seenMs : Infinity,
    };
  });
  const sorted = rows
    .map((row, index) => ({ row, index }))
    .sort((a, b) => a.row.sortKey - b.row.sortKey || a.index - b.index);
  const listings = sorted.slice(0, limit).map(({ row }) => ({
    key: row.key,
    name: row.name,
    priceLabel: row.priceLabel,
    markupText: row.markupText,
    tone: row.tone,
    medianLabel: row.medianLabel,
    offers: row.offers,
    iconSrc: row.iconSrc,
  }));
  return { listings, total: rows.length };
}
